```python
import json
import os
import sys
from datetime import datetime

INVENTORY_FILE = 'inventory.json'

def load_inventory():
    if os.path.exists(INVENTORY_FILE):
        with open(INVENTORY_FILE, 'r') as f:
            return json.load(f)
    return {'products': [], 'categories': [], 'transactions': []}

def save_inventory(data):
    with open(INVENTORY_FILE, 'w') as f:
        json.dump(data, f, indent=2, default=str)

def add_product(data, name, price, category, quantity):
    product_id = max([p['id'] for p in data['products']], default=0) + 1
    if category not in data['categories']:
        data['categories'].append(category)
    product = {'id': product_id, 'name': name, 'price': float(price), 'category': category, 'quantity': int(quantity), 'created_at': datetime.now().isoformat()}
    data['products'].append(product)
    data['transactions'].append({'type': 'add', 'product_id': product_id, 'quantity': int(quantity), 'timestamp': datetime.now().isoformat()})
    save_inventory(data)
    return product

def remove_product(data, product_id):
    product = None
    for p in data['products']:
        if p['id'] == product_id:
            product = p
            break
    if product is None:
        print(f'Product {product_id} not found')
        return None
    data['products'].remove(product)
    data['transactions'].append({'type': 'remove', 'product_id': product_id, 'timestamp': datetime.now().isoformat()})
    save_inventory(data)
    return product

def update_quantity(data, product_id, delta):
    for p in data['products']:
        if p['id'] == product_id:
            p['quantity'] += delta
            if p['quantity'] < 0:
                p['quantity'] = 0
            data['transactions'].append({'type': 'update', 'product_id': product_id, 'delta': delta, 'timestamp': datetime.now().isoformat()})
            save_inventory(data)
            return p
    print(f'Product {product_id} not found')
    return None

def search_products(data, query):
    results = []
    for p in data['products']:
        if query.lower() in p['name'].lower() or query.lower() in p['category'].lower():
            results.append(p)
    return results

def get_by_category(data, category):
    return [p for p in data['products'] if p['category'] == category]

def get_low_stock(data, threshold=5):
    return [p for p in data['products'] if p['quantity'] <= threshold]

def get_total_value(data):
    return sum(p['price'] * p['quantity'] for p in data['products'])

def get_transaction_history(data, product_id=None):
    if product_id:
        return [t for t in data['transactions'] if t.get('product_id') == product_id]
    return data['transactions']

def format_product(product):
    return f"[{product['id']}] {product['name']} - ${product['price']:.2f} x{product['quantity']} ({product['category']})"

def format_report(data):
    lines = ['=== Inventory Report ===']
    lines.append(f'Total products: {len(data["products"])}')
    lines.append(f'Total value: ${get_total_value(data):.2f}')
    lines.append(f'Categories: {", ".join(data["categories"])}')
    lines.append('')
    for cat in data['categories']:
        products = get_by_category(data, cat)
        lines.append(f'--- {cat} ({len(products)} items) ---')
        for p in products:
            lines.append(f'  {format_product(p)}')
    low = get_low_stock(data)
    if low:
        lines.append('')
        lines.append('!!! LOW STOCK ALERT !!!')
        for p in low:
            lines.append(f'  {format_product(p)}')
    return '\n'.join(lines)

def main():
    data = load_inventory()
    if len(sys.argv) < 2:
        print('Usage: python monolith.py <command> [args]')
        print('Commands: add, remove, update, search, report, low-stock, history')
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == 'add':
        if len(sys.argv) != 6:
            print('Usage: add <name> <price> <category> <quantity>')
            sys.exit(1)
        p = add_product(data, sys.argv[2], sys.argv[3], sys.argv[4], sys.argv[5])
        print(f'Added: {format_product(p)}')
    elif cmd == 'remove':
        if len(sys.argv) != 3:
            print('Usage: remove <product_id>')
            sys.exit(1)
        p = remove_product(data, int(sys.argv[2]))
        if p:
            print(f'Removed: {format_product(p)}')
    elif cmd == 'update':
        if len(sys.argv) != 4:
            print('Usage: update <product_id> <delta>')
            sys.exit(1)
        p = update_quantity(data, int(sys.argv[2]), int(sys.argv[3]))
        if p:
            print(f'Updated: {format_product(p)}')
    elif cmd == 'search':
        if len(sys.argv) != 3:
            print('Usage: search <query>')
            sys.exit(1)
        results = search_products(data, sys.argv[2])
        for p in results:
            print(format_product(p))
    elif cmd == 'report':
        print(format_report(data))
    elif cmd == 'low-stock':
        threshold = int(sys.argv[2]) if len(sys.argv) > 2 else 5
        low = get_low_stock(data, threshold)
        for p in low:
            print(format_product(p))
    elif cmd == 'history':
        pid = int(sys.argv[2]) if len(sys.argv) > 2 else None
        txns = get_transaction_history(data, pid)
        for t in txns:
            print(json.dumps(t))
    else:
        print(f'Unknown command: {cmd}')
        sys.exit(1)

if __name__ == '__main__':
    main()
